(function () {
  'use strict';

  var EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  var MIN_PASSWORD_LENGTH = 8;

  var form = document.getElementById('signup-form');
  var successMessage = document.getElementById('success-message');
  if (!form || !successMessage) return;

  function field(id) {
    return {
      input: document.getElementById(id),
      errorEl: document.getElementById(id + '-error')
    };
  }

  var fields = { email: field('email'), password: field('password'), confirm: field('confirm') };

  // Link each input to its error element for assistive tech.
  Object.keys(fields).forEach(function (id) {
    fields[id].input.setAttribute('aria-describedby', id + '-error');
  });

  function setError(id, message) {
    var f = fields[id];
    if (message) {
      f.input.setAttribute('aria-invalid', 'true');
      f.errorEl.textContent = message;
    } else {
      f.input.removeAttribute('aria-invalid');
      f.errorEl.textContent = '';
    }
  }

  // Returns an error message string, or '' when valid.
  function validateEmail(value) {
    if (!value) return 'Email is required.';
    if (!EMAIL_RE.test(value)) return 'Enter a valid email address.';
    return '';
  }

  function validatePassword(value) {
    if (!value) return 'Password is required.';
    if (value.length < MIN_PASSWORD_LENGTH) {
      return 'Password must be at least ' + MIN_PASSWORD_LENGTH + ' characters.';
    }
    return '';
  }

  function validateConfirm(confirmValue, passwordValue) {
    if (!confirmValue) return 'Please confirm your password.';
    if (confirmValue !== passwordValue) return 'Passwords do not match.';
    return '';
  }

  function validateField(id) {
    var v = fields[id].input.value;
    switch (id) {
      case 'email': return validateEmail(v);
      case 'password': return validatePassword(v);
      case 'confirm': return validateConfirm(v, fields.password.input.value);
    }
    return '';
  }

  // Clear a field's error live as the user fixes it.
  Object.keys(fields).forEach(function (id) {
    fields[id].input.addEventListener('input', function () {
      if (fields[id].errorEl.textContent) {
        setError(id, validateField(id));
      }
    });
  });

  form.addEventListener('submit', function (event) {
    event.preventDefault();

    var invalidIds = [];
    ['email', 'password', 'confirm'].forEach(function (id) {
      var message = validateField(id);
      setError(id, message);
      if (message) invalidIds.push(id);
    });

    if (invalidIds.length > 0) {
      fields[invalidIds[0]].input.focus();
      return;
    }

    // Success path: swap the form for a confirmation message, no navigation.
    form.hidden = true;
    successMessage.hidden = false;
    successMessage.focus();
  });

  successMessage.setAttribute('tabindex', '-1');
})();

