import { test, expect } from '@playwright/test';

test.beforeEach(async ({ page }) => {
  await page.goto('/');
});

test('submitting empty shows all three errors and focuses email', async ({ page }) => {
  await page.getByRole('button', { name: 'Sign up' }).click();

  await expect(page.locator('#email')).toHaveAttribute('aria-invalid', 'true');
  await expect(page.locator('#password')).toHaveAttribute('aria-invalid', 'true');
  await expect(page.locator('#confirm')).toHaveAttribute('aria-invalid', 'true');

  await expect(page.locator('#email-error')).not.toBeEmpty();
  await expect(page.locator('#password-error')).not.toBeEmpty();
  await expect(page.locator('#confirm-error')).not.toBeEmpty();

  // aria-describedby wiring
  await expect(page.locator('#email')).toHaveAttribute('aria-describedby', 'email-error');
  await expect(page.locator('#password')).toHaveAttribute('aria-describedby', 'password-error');
  await expect(page.locator('#confirm')).toHaveAttribute('aria-describedby', 'confirm-error');

  await expect(page.locator('#email')).toBeFocused();
});

test('typing a valid email clears only that error', async ({ page }) => {
  await page.getByRole('button', { name: 'Sign up' }).click();
  await expect(page.locator('#email-error')).not.toBeEmpty();

  await page.locator('#email').fill('user@example.com');
  await expect(page.locator('#email')).not.toHaveAttribute('aria-invalid', /.*/);
  await expect(page.locator('#email-error')).toBeEmpty();

  // Other errors remain untouched
  await expect(page.locator('#password-error')).not.toBeEmpty();
  await expect(page.locator('#confirm-error')).not.toBeEmpty();
  await expect(page.locator('#password')).toHaveAttribute('aria-invalid', 'true');
  await expect(page.locator('#confirm')).toHaveAttribute('aria-invalid', 'true');
});

test('password mismatch is caught on submit and fixed via input event', async ({ page }) => {
  const email = page.locator('#email');
  const password = page.locator('#password');
  const confirm = page.locator('#confirm');

  await email.fill('user@example.com');
  await password.fill('hunter2hunter2');
  await confirm.fill('different-password');
  await page.getByRole('button', { name: 'Sign up' }).click();

  await expect(confirm).toHaveAttribute('aria-invalid', 'true');
  await expect(page.locator('#confirm-error')).toHaveText('Passwords do not match.');

  // Fixing the field live-clears its error
  await confirm.fill('hunter2hunter2');
  await expect(confirm).not.toHaveAttribute('aria-invalid', /.*/);
  await expect(page.locator('#confirm-error')).toBeEmpty();
});

test('successful submit swaps form for success message without navigation', async ({ page }) => {
  await page.locator('#email').fill('user@example.com');
  await page.locator('#password').fill('hunter2hunter2');
  await page.locator('#confirm').fill('hunter2hunter2');
  await page.getByRole('button', { name: 'Sign up' }).click();

  await expect(page.locator('#signup-form')).toBeHidden();
  await expect(page.locator('#success-message')).toBeVisible();
  await expect(page.locator('#success-message')).toContainText('Account created successfully!');
});

